-- OMECOnnect: customers can submit and track their own concerns (complaints).
-- Run after phase8_drop_phone_requirement_for_linking.sql.
--
-- Before this, only admins could insert complaints and every complaint had to
-- belong to a verified OMECO account, so the app's Concerns form could not work.
-- Now any signed-in customer can file a concern (even before account
-- verification); the tracking number is generated by the database; customers see
-- only their own concerns; only staff can change status.

ALTER TABLE public.complaints
  ADD COLUMN IF NOT EXISTS user_id UUID REFERENCES public.users(id) ON DELETE CASCADE,
  ADD COLUMN IF NOT EXISTS municipality TEXT,
  ADD COLUMN IF NOT EXISTS barangay TEXT,
  ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT NOW();

ALTER TABLE public.complaints
  ALTER COLUMN tracking_number SET DEFAULT
    'OMC-' || to_char(NOW() AT TIME ZONE 'Asia/Manila', 'YYMMDD') || '-' ||
    upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 5));

ALTER TABLE public.complaints DROP CONSTRAINT IF EXISTS complaints_description_length;
ALTER TABLE public.complaints
  ADD CONSTRAINT complaints_description_length
  CHECK (char_length(btrim(description)) BETWEEN 10 AND 2000);

ALTER TABLE public.complaints DROP CONSTRAINT IF EXISTS complaints_type_allowed;
ALTER TABLE public.complaints
  ADD CONSTRAINT complaints_type_allowed
  CHECK (complaint_type IN ('Billing concerns', 'Payment problems', 'Power interruptions',
                            'Low voltage', 'New connection', 'Other'));

CREATE INDEX IF NOT EXISTS complaints_user_created_idx ON public.complaints (user_id, created_at DESC);

DROP POLICY IF EXISTS "Customers can view own complaints" ON public.complaints;
CREATE POLICY "Customers can view own complaints"
  ON public.complaints FOR SELECT TO authenticated
  USING (
    user_id = (SELECT auth.uid())
    OR EXISTS (
      SELECT 1 FROM public.customer_accounts AS ca
      WHERE ca.id = customer_account_id
        AND ca.user_id = (SELECT auth.uid())
        AND ca.verification_status = 'verified'
    )
    OR public.is_omeco_admin()
  );

DROP POLICY IF EXISTS "Customers can submit own concerns" ON public.complaints;
CREATE POLICY "Customers can submit own concerns"
  ON public.complaints FOR INSERT TO authenticated
  WITH CHECK (
    user_id = (SELECT auth.uid())
    AND status = 'submitted'
    AND (
      customer_account_id IS NULL
      OR EXISTS (
        SELECT 1 FROM public.customer_accounts AS ca
        WHERE ca.id = customer_account_id
          AND ca.user_id = (SELECT auth.uid())
          AND ca.verification_status = 'verified'
      )
    )
  );
